# PTX source for fp16 GEMM (A[M,K] * B[K,N] = C[M,N]) on SM80 (A100)
PTX_SOURCE = r"""
.version 8.5
.target sm_80
.address_size 64

// thread block tile dimensions
.visible .const .u32 TILE_X = 32;
.visible .const .u32 TILE_Y = 8;

.visible .entry gemm_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
{
    // -------------------------
    // load kernel parameters
    // -------------------------
    .reg .u64 %A, %B, %C;
    .reg .u32 %M, %K, %N;
    ld.param.u64 %A, [A_ptr];
    ld.param.u64 %B, [B_ptr];
    ld.param.u64 %C, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %K, [K];
    ld.param.u32 %N, [N];

    // -------------------------
    // thread / block indices
    // -------------------------
    .reg .u32 %tx, %ty, %bx, %by;
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bx, %ctaid.x;
    mov.u32 %by, %ctaid.y;

    // global row i and column j this thread will compute
    .reg .u32 %i, %j;
    mul.lo.u32 %i, %by, TILE_Y;
    add.u32 %i, %i, %ty;
    mul.lo.u32 %j, %bx, TILE_X;
    add.u32 %j, %j, %tx;

    // bounds check
    .reg .pred %p_valid;
    setp.ge.u32 %p_valid, %i, %M;    // i >= M ?
    @%p_valid bra DONE;              // if true, exit
    setp.ge.u32 %p_valid, %j, %N;    // j >= N ?
    @%p_valid bra DONE;              // if true, exit

    // -------------------------
    // accumulation (fp32)
    // -------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    // loop over k
    .reg .u32 %k;
    mov.u32 %k, 0;
LOOP_K:
    // ---- load A[i,k] (fp16) ----
    .reg .u64 %idxA, %addrA;
    mul.lo.u32 %idxA, %i, %K;        // i*K
    add.u32 %idxA, %idxA, %k;        // i*K + k
    cvt.u64.u32 %idxA, %idxA;
    mul.lo.u64 %addrA, %idxA, 2;     // *sizeof(half)
    add.u64 %addrA, %A, %addrA;
    .reg .f16 %a_val;
    ld.global.f16 %a_val, [%addrA];

    // ---- load B[k,j] (fp16) ----
    .reg .u64 %idxB, %addrB;
    mul.lo.u32 %idxB, %k, %N;        // k*N
    add.u32 %idxB, %idxB, %j;        // k*N + j
    cvt.u64.u32 %idxB, %idxB;
    mul.lo.u64 %addrB, %idxB, 2;
    add.u64 %addrB, %B, %addrB;
    .reg .f16 %b_val;
    ld.global.f16 %b_val, [%addrB];

    // ---- convert to fp32 and fma ----
    .reg .f32 %a_f32, %b_f32;
    cvt.rn.f32.f16 %a_f32, %a_val;
    cvt.rn.f32.f16 %b_f32, %b_val;
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // increment k
    add.u32 %k, %k, 1;
    setp.lt.u32 %p_valid, %k, %K;
    @%p_valid bra LOOP_K;

    // -------------------------
    // store result (fp16)
    // -------------------------
    .reg .f16 %c_half;
    cvt.rn.f16.f32 %c_half, %sum;

    .reg .u64 %idxC, %addrC;
    mul.lo.u32 %idxC, %i, %N;        // i*N
    add.u32 %idxC, %idxC, %j;        // i*N + j
    cvt.u64.u32 %idxC, %idxC;
    mul.lo.u64 %addrC, %idxC, 2;
    add.u64 %addrC, %C, %addrC;
    st.global.f16 [%addrC], %c_half;

DONE:
    ret;
}
"""

class ModelNew:
    """Drop‑in PyTorch model using the PTX GEMM kernel."""
    def __init__(self):
        # load the PTX module (provided by the harness)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"
        # allocate output
        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # launch configuration (tile = 32x8)
        TILE_X = 32
        TILE_Y = 8
        grid_x = (N + TILE_X - 1) // TILE_X
        grid_y = (M + TILE_Y - 1) // TILE_Y
        grid = (grid_x, grid_y, 1)
        block = (TILE_X, TILE_Y, 1)

        # arguments: raw device pointers + dimensions
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            int(M),
            int(K),
            int(N)
        ]

        # launch the kernel via the harness
        ptx_launch(self.module, "gemm_kernel", grid, block, args)

        return C
